 need(n.after.cpu.eip==0x410a80&&n.after.cpu.esp==old::frame+4&&n.after.cpu.ebp==0x92837465,"Real outer RET/EBP closure");need(n.checkpoint.cpu.eip==0x4c1a09&&n.checkpoint.cpu.esp==old::frame-12,"Actual live ST0 service-return checkpoint");
